// ===== 06 VDR — Build vendor reports =====
// Vendor Lead Report v2 (handoff, 2026-10-15). Input: one "Get vendor report" result per due vendor, in the order
// "Plan vendor requests" made them: the branded XLSX (binary "data") from LP-MCP GET /vdr/report.xlsx, built from LIVE
// data (lp_leads + market assignments + Five9), plus its X-VDR-* headers. Output: one item per vendor, ready to send,
// or a blocked/empty status. Nothing is sent from here.
//   - Freshness gate: the lead sync (max lp_leads.synced_at) must be under 6 hours old, else blocked stale_lead_sync
//     (Mark reads it in the run summary, whose subject then says ACTION NEEDED).
//   - LP report 135 is a CROSS-CHECK only, never a blocker: when a complete saved 135 feed from the last 36 hours
//     exists, a lead-count gap over 2% still sends and is listed in Mark's summary.
//   - The workbook must be the vendor's own (X-VDR-Vendor-Id), so no vendor can get another vendor's leads.
// Rev share (2026-10-13, unchanged): a vendor with rev_share=true also gets the "Payable Jobs" CSV from
// rpc/vdr_rev_share_data, and is blocked when that data is stale or a job has no source.
const INTERNAL_TO = 'm.richard@reecewindows.com';
const LEAD_SYNC_MAX_AGE_HOURS = 6;  // handoff: max(lp_leads.synced_at) older than this blocks the send
const CROSS_CHECK_GAP = 0.02;       // 135 vs live distinct-lead gap listed in the summary above this
const RTP_MAX_AGE_HOURS = 24;       // lp_job_milestones must have synced within this window (rev share only)
const JOBSTATUS_MAX_AGE_DAYS = 3;   // 133 Jobs By Status must have a contract this recent (rev share only)
const TZ = 'America/New_York';
const PAYABLE_COLS = ['Job #', 'Lead ID', 'Customer', 'Source', 'Contract Date', 'Released to Production Date', 'Sale Amount', 'Job Status'];
const XLSX_TYPE = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

function toCSV(rows) {
  return rows.map(r => r.map(v => { v = String(v ?? ''); return /[",\n\r]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(',')).join('\r\n') + '\r\n';
}
// Returns 'YYYY-MM-DD' or null. Accepts M/D/YYYY (with optional time) and YYYY-MM-DD.
function ymd(v) {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (m) { const y = m[3].length === 2 ? '20' + m[3] : m[3]; return `${y}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`; }
  return null;
}
const localDate = d => d.toLocaleDateString('en-CA', { timeZone: TZ });
function addDays(dateStr, n) { const d = new Date(dateStr + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
const money = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// Every date a person reads (file names, email text) is MM-DD-YYYY (Mark, 2026-10-14). Values kept for the database
// (log rows, payable ledger) stay YYYY-MM-DD.
const mdy = v => { const d = ymd(v); return d ? `${d.slice(5, 7)}-${d.slice(8, 10)}-${d.slice(0, 4)}` : (v == null ? '' : String(v)); };
const now = new Date();
const today = localDate(now);
const hoursSince = iso => { const t = Date.parse(iso || ''); return Number.isFinite(t) ? (now.getTime() - t) / 3600000 : Infinity; };
const headerOf = (h, name) => { if (!h) return null; const k = Object.keys(h).find(x => x.toLowerCase() === name); const v = k ? h[k] : null; return Array.isArray(v) ? v[0] : v; };

const plan = $('Plan vendor requests').all().map(i => i.json);
const res = $input.all();

// ---------- 0. Rev-share data (only rev-share vendors depend on it) ----------
let rs = null, rsError = null;
try { rs = $('Get rev-share data').first().json; } catch (e) { rsError = String((e && e.message) || e); }
if (rs && !Array.isArray(rs.vendors)) { rsError = rsError || 'rev-share data has no vendors list'; rs = null; }
const rsVendors = new Map(((rs && rs.vendors) || []).map(x => [String(x.vendor_id), x]));
// One answer per rev-share vendor: null = fine, else the block reason. Fails closed on any doubt.
function revShareBlock(v, rv) {
  if (!rs) return `rev_share_data_unavailable (${rsError || 'no data'})`;
  if (!rv) return 'rev_share_vendor_missing (vendor not returned by vdr_rev_share_data)';
  const syncH = hoursSince(rs.milestones_last_sync);
  if (syncH > RTP_MAX_AGE_HOURS) return `rtp_data_stale (lp_job_milestones last synced ${Number.isFinite(syncH) ? syncH.toFixed(1) + 'h ago' : 'never'})`;
  const lastContract = ymd(rs.jobstatus_last_contract);
  if (!lastContract || lastContract < addDays(today, -JOBSTATUS_MAX_AGE_DAYS)) return `job_status_data_stale (133 Jobs By Status last contract ${lastContract ? mdy(lastContract) : 'unknown'})`;
  const unattributed = Number(rs.rtp_unattributed_in_period || 0), unresolved = Number(rv.rtp_unresolved_in_period || 0);
  if (unattributed > 0 || unresolved > 0) return `rtp_jobs_without_source (${unattributed + unresolved}: ${unresolved} may be ${v.vendor_name}'s, ${unattributed} belong to no known source)`;
  return null;
}
const looksCancelled = p => /^lost$/i.test(String(p.bucket || '')) || /cancel|declin|dead/i.test(String(p.job_status || ''));

// ---------- 1. One report per due vendor ----------
const out = [];
let leadSyncedAt = null;
const gaps = [];
for (let i = 0; i < plan.length; i++) {
  const v = plan[i];
  const r = res[i] || { json: {} };
  const h = r.json.headers || null;
  const isTest = v.test === true;
  const isRev = v.rev_share === true || rsVendors.has(String(v.vendor_id));
  const rv = rsVendors.get(String(v.vendor_id)) || null;
  const base = {
    vendor_id: v.vendor_id, vendor_name: v.vendor_name, week_start: v.week_start, scheduled_for: v.scheduled_for,
    dry_run: isTest || v.dry_run !== false, test: isTest, lookback_days: v.lookback_days || 90,
    source_file: 'live: lp_leads + Five9 (GET /vdr/report.xlsx)', source_row_count: null, feed_received_at: null,
    internal_to: INTERNAL_TO, date: today,
    rev_share: isRev, period_start: rv ? rv.period_start : null, period_end: rv ? rv.period_end : null,
    frequency: v.frequency === 'monthly' ? 'monthly' : 'weekly',   // 2026-10-14: per-vendor, set in the dashboard
  };
  const cadence = base.frequency === 'monthly' ? 'Monthly' : 'Weekly';
  const block = reason => out.push({ json: { ...base, status: 'blocked', reason } });
  // The workbook itself: an HTTP error, a missing file or another vendor's file sends nothing.
  if (r.json.error || !h) { block(`report_unavailable (${JSON.stringify(r.json.error || 'no response').slice(0, 200)})`); continue; }
  if (Number(r.json.statusCode || 200) !== 200 || !r.binary || !r.binary.data) { block(`report_unavailable (status ${r.json.statusCode ?? '?'}, no file)`); continue; }
  if (String(headerOf(h, 'x-vdr-vendor-id')) !== String(v.vendor_id)) { block(`report_mismatch (asked for vendor ${v.vendor_id}, got ${headerOf(h, 'x-vdr-vendor-id') ?? 'none'})`); continue; }
  const synced = headerOf(h, 'x-vdr-lead-synced-at');
  leadSyncedAt = synced || leadSyncedAt;
  const syncH = hoursSince(synced);
  if (syncH > LEAD_SYNC_MAX_AGE_HOURS) { block(`stale_lead_sync (Lead Perfection leads last synced ${Number.isFinite(syncH) ? syncH.toFixed(1) + 'h ago' : 'never'})`); continue; }
  const leadCount = Number(headerOf(h, 'x-vdr-lead-count'));
  const fileName = String(headerOf(h, 'x-vdr-file-name') || `Reece_Vendor_Lead_Report_${v.vendor_id}_${today}.xlsx`);
  const [startDate, endDate] = String(headerOf(h, 'x-vdr-window') || '').split('..');
  if (!Number.isInteger(leadCount) || leadCount < 0) { block('report_unreadable (no lead count)'); continue; }
  // Cross-check against the saved 135 feed (never a blocker).
  let crossCheck = null;
  const feedLeads = headerOf(h, 'x-vdr-feed-leads');
  if (feedLeads != null && feedLeads !== '') {
    const fl = Number(feedLeads);
    const gap = Math.abs(leadCount - fl) / Math.max(leadCount, fl, 1);
    crossCheck = { feed_leads: fl, gap_pct: Math.round(gap * 1000) / 10, received_at: headerOf(h, 'x-vdr-feed-received-at') };
    if (gap > CROSS_CHECK_GAP) gaps.push(`${v.vendor_name}: live ${leadCount} leads vs 135 feed ${fl} (${crossCheck.gap_pct}% apart)`);
  }
  base.cross_check = crossCheck;
  const to = (v.recipients_to || []).filter(Boolean), cc = (v.recipients_cc || []).filter(Boolean);
  if (!base.dry_run && to.length === 0) { block('no_recipients (vendor is live but recipients_to is empty)'); continue; }
  if (isRev) { const why = revShareBlock(v, rv); if (why) { block(why); continue; } }
  if (leadCount === 0) { out.push({ json: { ...base, status: 'empty', lead_count: 0, reason: `no leads from ${(v.lp_sub_sources || []).join(', ')} entered ${mdy(startDate)} to ${mdy(endDate)}` } }); continue; }
  const sendTo = base.dry_run ? INTERNAL_TO : to.join(', ');
  // BCC (Mark, 2026-10-15): Mark always, plus the vendor's recipients_bcc from the dashboard, de-duplicated.
  const bccList = base.dry_run ? [] : [...new Set([INTERNAL_TO, ...(v.recipients_bcc || [])].map(s => String(s || '').trim().toLowerCase()).filter(Boolean))];
  let body = `Hello,\n\nAttached is your ${cadence.toLowerCase()} lead report from Reece Windows & Doors.\n\nIt lists all ${leadCount} leads ${v.vendor_name} provided to Reece in the last ${base.lookback_days} days (entered ${mdy(startDate)} to ${mdy(endDate)}), with each lead's calls, appointment and sale status as of today. The Summary tab totals them by market and by week, the Leads tab has one row per lead, and the Definitions tab explains each column.`;
  const prefix = isTest ? '[TEST] ' : (base.dry_run ? '[DRY RUN] ' : '');
  const item = {
    json: {
      ...base, status: 'ok', lead_count: leadCount, since: startDate || null, out_file: fileName,
      to: sendTo, cc: base.dry_run ? '' : cc.join(', '), bcc: bccList.join(', '),
      recipients: base.dry_run ? `${isTest ? 'TEST' : 'DRY RUN'} -> ${INTERNAL_TO} (would go to: ${to.join(', ') || 'no recipients set'})` : [...to, ...cc].join(', ') + (bccList.length ? ` · bcc ${bccList.join(', ')}` : ''),
      subject: prefix + `Reece Windows & Doors - ${cadence} Lead Report - ${v.vendor_name} - ${mdy(today)}`,
      attachment_props: 'data',
    },
    binary: { data: { ...r.binary.data, fileName, mimeType: XLSX_TYPE, fileExtension: 'xlsx' } },
  };
  if (isRev) {
    // Payable Jobs: every job released to production in the prior pay period, minus jobs already listed
    // for this vendor (the vdr_payable_jobs ledger, dry run and live kept apart).
    const all = Array.isArray(rv.payable) ? rv.payable : [];
    const fresh = all.filter(p => p.already_listed !== true);
    const previously = all.length - fresh.length;
    const total = fresh.reduce((s, p) => s + Number(p.gross_cents || 0), 0) / 100;
    const ps = rv.period_start, pe = rv.period_end;
    const slug = v.vendor_name.replace(/[^A-Za-z0-9]+/g, '_').replace(/^_|_$/g, '');
    item.json.payable_count = fresh.length;
    item.json.payable_total = Math.round(total * 100) / 100;
    item.json.previously_listed = previously;
    item.json.cancel_flagged = fresh.filter(looksCancelled).map(p => `${p.lp_job_id} (${p.job_status})`);
    item.json.payable_rows = fresh.map(p => ({
      vendor_id: v.vendor_id, vendor_name: v.vendor_name, lp_job_id: String(p.lp_job_id), lp_lead_id: p.lp_lead_id ?? null,
      sub_source: p.sub_source ?? null, rtp_date: ymd(p.rtp_date), period_start: ps, period_end: pe,
      gross_cents: p.gross_cents ?? null, job_status: p.job_status ?? null, dry_run: base.dry_run,
    }));
    if (fresh.length) {
      const payName = `Reece_${slug}_Payable_Jobs_${mdy(ps)}_to_${mdy(pe)}.csv`;
      const payCsv = toCSV([PAYABLE_COLS, ...fresh.map(p => [
        p.lp_job_id, p.lp_lead_id ?? '', p.customer_name ?? '', p.sub_source ?? '', mdy(p.contract_date),
        mdy(p.rtp_date), Number(p.gross_cents || 0) / 100, p.job_status ?? '',
      ])]);
      item.binary.payable = await this.helpers.prepareBinaryData(Buffer.from(payCsv, 'utf8'), payName, 'text/csv');
      item.json.payable_file = payName;
      item.json.attachment_props = 'data,payable';
      body += `\n\nAlso attached: Payable Jobs. Payable jobs released to production ${mdy(ps)} to ${mdy(pe)}: ${fresh.length}, total $${money(total)}.`;
    } else {
      body += `\n\nNo jobs released to production ${mdy(ps)} to ${mdy(pe)}.`;
    }
  }
  body += `\n\nQuestions: ${INTERNAL_TO}\n\nReece Windows & Doors`;
  item.json.body = body;
  out.push(item);
}
// Run-level info rides on the first item so the summary step can report it.
if (out.length) out[0].json.feed_info = {
  live: true, lead_synced_at: leadSyncedAt, cross_check_gaps: gaps, test: plan.some(v => v.test === true),
  rev_share: rs ? { milestones_last_sync: rs.milestones_last_sync, jobstatus_last_contract: rs.jobstatus_last_contract,
                    rtp_unmatched_detail: rs.rtp_unmatched_detail || [], error: rsError } : { error: rsError || 'no data' },
};
return out;

// ===== 06 VDR — Summarize & build log rows =====
// Runs after the send branch. Joins each vendor's build result with its Gmail result,
// produces one vdr_send_log row per vendor, one vdr_payable_jobs row per payable job actually EMAILED
// (rev share, 2026-10-13), and one plain-text summary for Mark.
// Vendor Lead Report v2 (2026-10-15): the reports come from live data, so the summary names the lead sync time and
// any gap over 2% against the saved LP report 135 feed (a cross-check, never a blocker). A test send says so.
const built = $('Build vendor reports').all().map(i => i.json);
let sends = [];
try { sends = $('Send vendor report').all().map(i => i.json); } catch (e) { sends = []; }  // no ok items -> node never ran

const okBuilt = built.filter(b => b.status === 'ok');
const execId = String($execution.id ?? '');
const money = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// Dates a person reads are MM-DD-YYYY, timestamps MM-DD-YYYY h:mm AM ET (Mark, 2026-10-14).
const mdy = v => { const m = String(v ?? '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${m[2]}-${m[3]}-${m[1]}` : (v == null ? '-' : String(v)); };
const mdyTime = iso => { const d = new Date(iso || ''); if (!iso || isNaN(d.getTime())) return '-'; const p = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', month: '2-digit', day: '2-digit', year: 'numeric', hour: 'numeric', minute: '2-digit' }).formatToParts(d); const g = t => (p.find(x => x.type === t) || {}).value; return `${g('month')}-${g('day')}-${g('year')} ${g('hour')}:${g('minute')} ${g('dayPeriod')} ET`; };
const rows = [], lines = [], payableRows = [];
let s = 0;
for (const b of built) {
  let status = b.status, reason = b.reason || null;
  let sentOk = false;
  if (b.status === 'ok') {
    const g = sends[okBuilt.indexOf(b)];
    sentOk = !!(g && !g.error && (g.id || (Array.isArray(g.labelIds) && g.labelIds.includes('SENT'))));
    status = sentOk ? 'sent' : 'failed';
    if (!sentOk) reason = 'gmail_error: ' + JSON.stringify(g?.error ?? g ?? 'no result').slice(0, 300);
    if (sentOk) s++;
  }
  rows.push({
    vendor_id: b.vendor_id, vendor_name: b.vendor_name, week_start: b.week_start, scheduled_for: b.scheduled_for,
    dry_run: b.dry_run, status, lead_count: b.lead_count ?? null, recipients: b.recipients ?? null,
    out_file: b.out_file ?? null, reason, source_file: b.source_file, source_row_count: b.source_row_count,
    feed_received_at: b.feed_received_at, n8n_execution_id: execId,
  });
  // The ledger gets a job only when its email went out: a failed send must be listable next hour.
  if (sentOk && Array.isArray(b.payable_rows)) for (const p of b.payable_rows) payableRows.push({ ...p, n8n_execution_id: execId });
  const label = { sent: b.test ? 'SENT (test, to Mark only)' : b.dry_run ? 'SENT (dry run, to Mark only)' : 'SENT', failed: 'FAILED', blocked: 'BLOCKED', empty: 'NO LEADS' }[status];
  let line = `- ${b.vendor_name}${b.frequency === 'monthly' ? ' (monthly)' : ''}: ${label}${b.lead_count != null ? ` · ${b.lead_count} leads` : ''}${b.recipients && status === 'sent' ? ` · ${b.recipients}` : ''}${reason ? ` · ${reason}` : ''}`;
  if (b.rev_share && status !== 'blocked') {
    line += ` · payable ${b.payable_count ?? 0} jobs $${money(b.payable_total)} (${mdy(b.period_start)} to ${mdy(b.period_end)})`;
    if (b.previously_listed) line += ` · ${b.previously_listed} previously listed, not repeated`;
    if (Array.isArray(b.cancel_flagged) && b.cancel_flagged.length) line += ` · CHECK, looks cancelled: ${b.cancel_flagged.join(', ')}`;
  } else if (b.rev_share) {
    line += ' · rev share: payable jobs NOT sent';
  }
  lines.push(line);
}
const fi = built[0]?.feed_info || {};
const count = st => rows.filter(r => r.status === st).length;
const problems = count('failed') + count('blocked');
const allDry = rows.every(r => r.dry_run);
const date = built[0]?.date || '';
const subject = `${fi.test ? '[TEST] ' : allDry ? '[DRY RUN] ' : ''}${problems ? 'ACTION NEEDED - ' : ''}Vendor lead reports: ${count('sent')} sent, ${count('blocked')} blocked, ${count('failed')} failed, ${count('empty')} no leads (${mdy(date)})`;
const rsi = fi.rev_share || {};
const unmatchedRtp = Array.isArray(rsi.rtp_unmatched_detail) ? rsi.rtp_unmatched_detail : [];
const body = [
  `Vendor lead reports - ${mdy(date)}${fi.test ? ' (TEST send, to Mark only)' : ''}`, '',
  ...lines, '',
  `Data: live from Lead Perfection (leads last synced ${mdyTime(fi.lead_synced_at)}) and Five9 (calls).`,
  Array.isArray(fi.cross_check_gaps) && fi.cross_check_gaps.length ? `Cross-check with LP report 135 (sent anyway; over 2% apart):\n${fi.cross_check_gaps.map(g => `  ${g}`).join('\n')}` : null,
  `Rev-share data: lp_job_milestones synced ${mdyTime(rsi.milestones_last_sync)} · 133 Jobs By Status last contract ${rsi.jobstatus_last_contract ? mdy(rsi.jobstatus_last_contract) : '-'}${rsi.error ? ` · NOT USABLE: ${rsi.error}` : ''}`,
  unmatchedRtp.length ? `Jobs released to production this pay period that 133 Jobs By Status has not reported yet (attributed by LP lead source; a rev-share vendor is blocked only when one is theirs or has no source):\n${unmatchedRtp.map(u => `  job ${u.lp_job_id} · RTP ${mdy(u.rtp_date)} · source ${u.fallback_source || 'UNKNOWN'}`).join('\n')}` : null,
  // Mark, 2026-10-14: the summary lists only what was sent. No list of LP sub-sources without a vendor
  // (it ran to 60+ lines), no blank-source count; the status legend only when something did not go out.
  problems ? '' : null,
  problems ? 'BLOCKED = nothing was sent because a check failed. FAILED = the email did not go out. Both retry with the next daily run (7:15 AM ET), up to 3 times this period (week or month).' : null,
  '',
  `n8n execution: ${execId}`,
].filter(l => l !== null).join('\n');
return [{ json: { log_rows: rows, subject, body, problems, internal_to: built[0]?.internal_to, payable_rows: payableRows, payable_count: payableRows.length } }];

// ===== 06 VDR — Prepare feed for database =====
// The user, 2026-10-15: save each day's 90-day feed so a manual run ("Send now (saved feed)") can use it, "but I
// want to make sure that each day when the last 90 days arrive we should be updating the pre existing values to
// match instead of add the duplicates." So the feed is stored as ONE row per LP lead (vdr_feed_leads, keyed on the
// lead id) and each feed overwrites it. The row kept per lead is the one Build vendor reports would pick, by the
// same rank (current beats Superseded, then newest entry date, then newest appointment, then latest in the file),
// so a report built from the saved copy lists exactly what the email would have. `_order` keeps the file order.
// This branch runs beside the send path: a save problem never stops or changes a send. A feed that fails the
// builder's own checks (no CSV, no header, missing columns, a row with no lead id or entry date) is not saved.
// Output: chunks of CHUNK leads for rpc/vdr_store_feed_chunk, or one { save_failed } item.
const CHUNK = 2000;
// The feed columns the report builder reads (its OUT_COLS, REQUIRED and ApptDate). Nothing else is stored.
const KEEP = ['id', 'entrydate', 'FirstName', 'lastname', 'Phone', 'Email', 'Address1', 'city', 'state', 'Zip',
  'SourceSubDescr', 'dspdescr', 'lastresult', 'ApptDate', 'JobStatus', 'GSA', 'Category', 'SDate'];
const REQUIRED = ['id', 'entrydate', 'SourceSubDescr', 'dspdescr', 'Category', 'SDate'];

// parseCSV and ymd are copied verbatim from Build vendor reports: both steps must read the file the same way.
function parseCSV(text) {
  const rows = []; let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c === '\r') { }
    else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => r.some(v => String(v).trim() !== ''));
}
function ymd(v) {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (m) { const y = m[3].length === 2 ? '20' + m[3] : m[3]; return `${y}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`; }
  return null;
}
const fail = reason => [{ json: { save_failed: reason } }];

const mail = $input.all();
let it = null, idx = -1, key = null;
for (let i = 0; i < mail.length; i++) {
  const bin = mail[i].binary ?? {};
  if (!mail[i].json || !mail[i].json.id) continue;
  const k = Object.keys(bin).find(x => /\.csv$/i.test(bin[x]?.fileName ?? ''));
  if (k) { it = mail[i]; idx = i; key = k; break; }
}
if (!it) return fail('no_csv_attachment');
const receivedMs = Number(it.json.internalDate) || Date.parse(it.json.date || '');
if (!Number.isFinite(receivedMs)) return fail('no_received_date');
const text = (await this.helpers.getBinaryDataBuffer(idx, key)).toString('utf8').replace(/^﻿/, '');
const rows = parseCSV(text);
const h = rows.findIndex((r, i) => i < 10 && r.some(c => String(c).trim() === 'SourceSubDescr'));
if (h === -1) return fail('header_not_found');
const header = rows[h].map(c => String(c).trim());
const lower = header.map(c => c.toLowerCase());
const col = {};
for (const name of KEEP) col[name] = lower.indexOf(name.toLowerCase());   // case-insensitive, as the builder
const missing = REQUIRED.filter(n => col[n] === -1);
if (missing.length) return fail('missing_columns: ' + missing.join(', '));
const data = rows.slice(h + 1);
if (!data.length) return fail('feed_empty');
const noId = data.filter(r => !String(r[col.id] ?? '').trim()).length;
if (noId) return fail(`rows_missing_lead_id (${noId})`);
const badDate = data.filter(r => !ymd(r[col.entrydate])).length;
if (badDate) return fail(`rows_with_bad_entry_date (${badDate})`);

// Kept columns, in feed order, with the feed's own spelling (the builder looks them up case-insensitively).
const kept = header.filter((c, i) => KEEP.some(k => col[k] === i));
const keptIdx = kept.map(c => header.indexOf(c));
// One row per lead, the builder's rank verbatim.
const cell = (r, n) => { const i = col[n]; return i === -1 || i === undefined ? '' : String(r[i] ?? '').trim(); };
const rank = (r, i) => [/^superseded$/i.test(cell(r, 'Category')) ? 0 : 1, ymd(r[col.entrydate]) || '', ymd(cell(r, 'ApptDate')) || '', i];
const better = (a, b) => { for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] > b[k]; return false; };
const best = new Map();
data.forEach((r, i) => {
  const id = String(r[col.id]).trim();
  const cur = best.get(id); const rk = rank(r, i);
  if (!cur) best.set(id, { r, rk, order: best.size });
  else if (better(rk, cur.rk)) best.set(id, { r, rk, order: cur.order });   // keeps the lead's first place in the file
});
const leads = [...best.entries()].map(([id, x]) => {
  const row = { _order: x.order };
  kept.forEach((c, j) => { row[c] = String(x.r[keptIdx[j]] ?? ''); });
  return { lead_id: id, entry_date: ymd(x.r[col.entrydate]), sub_source: cell(x.r, 'SourceSubDescr') || null, row };
});
const run = {
  gmail_message_id: String(it.json.id),
  received_at: new Date(receivedMs).toISOString(),
  source_file: it.binary[key].fileName || null,
  header: kept,
  raw_row_count: data.length,
  lead_count: leads.length,
  window_start: data.map(r => ymd(r[col.SDate])).find(Boolean) || null,
};
const out = [];
for (let i = 0; i < leads.length; i += CHUNK) out.push({ json: { run, leads: leads.slice(i, i + CHUNK) } });
return out;

