// ===== 06 VDR — Make test vendor due =====
// "Send now" with a test vendor id (the user, 2026-10-15): every dry-run vendor is switched off, so a test cannot
// come from vdr_due_vendors. This builds the same "due" shape for ONE vendor read from vdr_vendor_config, forced to
// dry run and marked as a test: it goes to Mark only, whatever the vendor's own settings say, and changes nothing in
// vdr_vendor_config. Its send-log row is a dry-run row, which never counts against a live vendor's period.
const TZ = 'America/New_York';
const id = Number($('Send now settings').first().json.test_vendor_id);
const rows = $input.all().map(i => i.json).filter(r => r && r.id != null);
if (!rows.length) throw new Error(`No vendor with id ${id} in vdr_vendor_config. Nothing was sent or logged.`);
const c = rows[0];
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
const d = new Date(today + 'T12:00:00Z');
const monthly = c.frequency === 'monthly';
if (monthly) d.setUTCDate(1); else d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
const period = d.toISOString().slice(0, 10);
return [{ json: {
  test: true,
  due: [{
    vendor_id: c.id, vendor_name: c.vendor_name, lp_sub_sources: c.lp_sub_sources || [],
    recipients_to: c.recipients_to || [], recipients_cc: c.recipients_cc || [], recipients_bcc: c.recipients_bcc || [],
    dry_run: true, test: true, rev_share: c.rev_share === true, lookback_days: c.lookback_days || 90,
    frequency: monthly ? 'monthly' : 'weekly', week_start: period, period_start: period,
    scheduled_for: new Date().toISOString(),
  }],
} }];

// ===== 06 VDR — Plan vendor requests =====
// One item per due vendor; "Get vendor report" asks LP-MCP for that vendor's workbook (GET /vdr/report.xlsx).
// Vendor Lead Report v2 (handoff, 2026-10-15): the report is built from LIVE data (lp_leads + Five9), so a send no
// longer waits on the LP report 135 email. The due list comes from the test button when it ran, else vdr_due_vendors.
let cfg;
try { cfg = $('Make test vendor due').first().json; } catch (e) { cfg = $('Get due vendors').first().json; }
const due = Array.isArray(cfg.due) ? cfg.due : [];
const asOf = new Date().toISOString();
return due.map(v => ({ json: { ...v, as_of: asOf } }));
